function addDays(iso,n){if(!iso)return '';const d=new Date(iso+'T12:00:00Z');if(Number.isNaN(d.getTime()))return '';d.setUTCDate(d.getUTCDate()+Number(n||0));return d.toISOString().slice(0,10)}
