function bars(title,items,key,format=fmt){
 const max=Math.max(1,...items.map(x=>x[1])),flavors=items.some(([n])=>flavorColor(n));
 return `<section class="panel ${flavors?'flavor-panel':''}"><div class="panel-head"><h2>${title}</h2>${key?`<small>${T('Click to filter','اضغط للتصفية')}</small>`:''}</div><div class="bars">${items.slice(0,10).map(([n,v])=>`<button class="bar-row" ${key?`data-filter="${esc(key)}" data-value="${esc(n)}"`:'disabled'}><span>${esc(key===STATUS_FIELD?statusText(n,state.lang):key==='Visit Hour'?display(key,n):n)}</span><span class="track"><i style="width:${v/max*100}%;${flavorColor(n)?'background:'+flavorColor(n):''}"></i></span><b>${format(v)}</b></button>`).join('')||empty()}</div></section>`;
}
