function card(name,value,note,accent=''){return `<section class="metric ${accent}"><span>${name}</span><strong>${value}</strong><small>${note}</small></section>`}
function dashboard(rs){
 const k=kpis(rs),stores=latest(rs),pr=currentPresence(),prev=previousPeriodRows(rs),pk=kpis(prev);
 const delta=(a,b,percent=false)=>{if(!prev.length||a==null||b==null)return '—';const d=(a-b)*(percent?100:1);return `${d>=0?'↑':'↓'} ${fmt(Math.abs(d),1)}${percent?'%':''}`};
 const dates=group(rs,'_date').filter(x=>x[0]!=='—').sort((a,b)=>a[0].localeCompare(b[0])).slice(-30), tdms=group(rs,'Rep').slice(0,5), areas=group(rs,'RTM').slice(0,5);
 const max=Math.max(1,...dates.map(x=>x[1]));
 const pts=dates.map((x,i)=>`${dates.length<2?50:(i/(dates.length-1))*100},${92-(x[1]/max)*72}`).join(' ');
 const totalAreas=Math.max(1,areas.reduce((a,x)=>a+x[1],0));
 const colors=['#11a8ff','#1669ee','#ffc31b','#ff8b1f','#e56b52'];
 let offset=0;const stops=areas.map((x,i)=>{const a=offset/totalAreas*100;offset+=x[1];const b=offset/totalAreas*100;return `${colors[i%colors.length]} ${a}% ${b}%`}).join(',');
 return `${heroHTML()}
 <div class="mock-kpis">
  ${mockKpi('▦',T('Total Stores','إجمالي المحلات'),fmt(k.stores),delta(k.stores,pk.stores),'blue')}
  ${mockKpi('●',T('Visited Stores','المحلات المزارة'),fmt(k.stores),delta(k.stores,pk.stores),'cyan')}
  ${mockKpi('▥',T('Gorilla presence','تواجد جوريلا'),pct(k.presence),T('Latest outlet visit','آخر زيارة للمحل'),'green')}
  ${mockKpi('♟',T('Active TDMs','TDMs النشطين'),fmt(unique(rs,'Rep')),delta(unique(rs,'Rep'),unique(prev,'Rep')),'yellow')}
 </div>
 <div class="mock-chart-grid">
  <section class="mock-panel trend-panel"><div class="mock-panel-head"><h2>${T('Visits Trend','اتجاه الزيارات')}</h2><span>${T('Visits / Date','الزيارات / التاريخ')}</span></div>${trendChart(dates,{esc,fmt,T})}</section>
  <section class="mock-panel"><div class="mock-panel-head"><h2>${T('Visits by Area','الزيارات حسب المنطقة')}</h2></div><div class="area-donut-wrap"><div class="area-donut" style="background:conic-gradient(${stops||'#123 0 100%'})"><div><b>${fmt(k.visits)}</b><small>${T('Visits','زيارة')}</small></div></div><div class="area-legend">${areas.map((x,i)=>`<button data-filter="RTM" data-value="${esc(x[0])}"><i style="background:${colors[i%colors.length]}"></i><span>${esc(x[0])}</span><b>${fmt(x[1]/totalAreas*100,0)}%</b></button>`).join('')}</div></div></section>
  <section class="mock-panel"><div class="mock-panel-head"><h2>${T('Top TDMs','أفضل TDMs')}</h2><button data-tab="performance">${T('View All','عرض الكل')}</button></div><div class="tdm-rank">${tdms.map((x,i)=>`<button data-filter="Rep" data-value="${esc(x[0])}"><em>${i+1}</em><span class="avatar-dot">${esc(String(x[0]||'?').slice(0,1).toUpperCase())}</span><strong>${esc(x[0])}</strong><b>${fmt(x[1])}</b></button>`).join('')||empty()}</div></section>
 </div>
 <div class="quick-cards dashboard-quick">${quickCard('geo','pin',T('MAPS','الخرائط'),T('Explore store locations','استكشف مواقع المحلات'),'blue')}${quickCard('photos','camera',T('PHOTO GALLERY','معرض الصور'),T('View store images','استعرض صور المحلات'),'teal')}${quickCard('reports','doc',T('REPORTS','التقارير'),T('Generate insights','أنشئ تقارير ونتائج'),'violet')}${quickCard('market','target',T('ATTENTION REQUIRED','يتطلب الانتباه'),T('Open business signals','افتح إشارات المتابعة'),'gold')}</div>
 <details class="filter-drawer dashboard-filters"><summary><span>⚙ ${T('Advanced filters & Cycle / Week','الفلاتر المتقدمة والسايكل / الأسبوع')}</span><b>${fmt(rs.length)} ${T('visits','زيارة')}</b></summary>${filtersHTML()}</details>
 <section class="presence-quick"><div><strong>${fmt(pr.presentCount)}</strong>${T('Clients with Gorilla in period','عملاء بها جوريلا في الفترة')}</div><div><strong>${fmt(pr.cumulativeCount)}</strong>${T('Cumulative clients','عملاء تراكميون')}</div><div><strong>${duration(k.duration)}</strong>${T('Average visit time','متوسط وقت الزيارة')}</div><button data-tab="presence">${T('View Gorilla stores & history','عرض محلات جوريلا والتاريخ')} ↗</button></section>${comparisonView(rs,comparisonMode,{esc,fmt,T,filters:state.filters})}`;
}
function mockKpi(icon,title,value,note,tone){return `<section class="mock-kpi ${tone}"><span class="mock-kpi-icon">${metricIcons[tone]||icon}</span><div><small>${title}</small><strong>${value}</strong></div><em>${note}${/^[↑↓]/.test(note)?`<small>${T('vs previous period','عن الفترة السابقة')}</small>`:''}</em></section>`}

function attentionRow(name,value,tab){return `<button class="attention-row" data-tab="${tab}"><span>${name}</span><b>${fmt(value)}</b><i>›</i></button>`}
let stopHero=()=>{};
function heroHTML(){return renderHero(state.appSettings?.hero||{},state.lang==='ar');}
function previousPeriodRows(){
 const f={...state.filters};let from='',to='';
 if(f._cycle){const c=cycleInfo(f._cycle);const start=f._cycle;if(f._week){const ws=addDays(start,(Number(f._week)-1)*7);from=addDays(ws,-7);to=addDays(ws,-1);}else{from=addDays(start,-14);to=addDays(start,-1)}}
 else if(f.from||f.to){const a=f.from||f.to,b=f.to||f.from;const days=Math.max(1,Math.round((new Date(b)-new Date(a))/86400000)+1);from=addDays(a,-days);to=addDays(a,-1)}
 else {const dates=rows.map(r=>r._date).filter(Boolean).sort();to=dates.at(-1)||'';from=to?addDays(to,-6):'';if(from){const pto=addDays(from,-1);from=addDays(from,-7);to=pto}}
 return filterRows(rows,{...f,_cycle:'',_week:'',from,to});
}
function lostStores(all,filters){const period=filterRows(all,filters),latestPeriod=latest(period),ids=new Set();for(const r of latestPeriod){if(r._presence!==false||!r._id)continue;const prior=all.some(x=>x._id===r._id&&x._presence===true&&visitStamp(x)<visitStamp(r));if(prior)ids.add(r._id)}return [...ids]}
function navHTML(){const groups=[['OVERVIEW',['dashboard']],['GORILLA',['presence','presencetrends','availability','execution','market']],['FIELD TEAM',['performance','geo']],['STORES',['stores','photos','all']],['REPORTING & CONTROL',['reports','health','optional']]];let out='';for(const [title,items] of groups){const visible=items.filter(k=>allowedPage(k)&&state.settings.tabs[k]!==false);if(!visible.length)continue;out+=`<div class="nav-group"><small>${title}</small>${visible.map(k=>`<button data-tab="${k}" class="nav-item ${state.tab===k?'active':''}"><span>${icons[k]}</span>${label(k)}</button>`).join('')}</div>`}if(state.me?.role==='owner')out+=`<div class="nav-group owner-nav"><small>OWNER</small><button data-tab="settings" class="nav-item ${state.tab==='settings'?'active':''}"><span>${icons.settings}</span>${label('settings')}</button><button data-tab="users" class="nav-item ${state.tab==='users'?'active':''}"><span>${icons.users}</span>${label('users')}</button></div>`;out+=`<div class="nav-group"><button data-tab="notifications" class="nav-item ${state.tab==='notifications'?'active':''}"><span>♧</span>${label('notifications')}</button></div>`;return out}
function reportsView(rs){const k=kpis(rs),pr=currentPresence();return `<div class="report-grid">${reportCard('presence',T('Gorilla Presence Report','تقرير تواجد جوريلا'),`${fmt(pr.presentCount)} ${T('present ·','متواجد ·')} ${fmt(pr.repeatedCount)} ${T('repeated absence','غياب متكرر')}`)}${reportCard('performance',T('TDM Performance Report','تقرير أداء TDMs'),`${fmt(unique(rs,'Rep'))} TDMs · ${duration(k.duration)} ${T('avg visit','متوسط زيارة')}`)}${reportCard('availability',T('Availability & SKU Report','تقرير التوافر والأصناف'),`${fmt(k.availability,1)} / 6 ${T('average availability','متوسط التوافر')}`)}${reportCard('market',T('Opportunity & Attention Report','تقرير الفرص والتنبيهات'),`${fmt(pr.repeatedCount+lostStores(rows,state.filters).length)} ${T('priority signals','إشارات أولوية')}`)}${reportCard('all',T('Full Visit Export','تصدير الزيارات الكامل'),`${fmt(rs.length)} ${T('matching visits','زيارة مطابقة')}`)}</div><section class="panel"><h2>${T('Reporting rules','قواعد التقارير')}</h2><p>${T('Every report respects your RTM access plus Cycle, Week and all active filters. Export permission is checked by the server.','كل تقرير يحترم صلاحية RTM والسايكل والأسبوع وكل الفلاتر المفعلة. صلاحية التصدير يتم التحقق منها على السيرفر.')}</p></section>`}
function reportCard(tab,title,note){return `<section class="report-card"><span>${icons[tab]||'▤'}</span><h2>${title}</h2><p>${note}</p><div><button data-tab="${tab}">${T('Open','فتح')}</button>${allowedAction('export')?`<button class="accent" data-report-export="${tab}">Excel ↗</button>`:''}</div></section>`}
function usersView(){if(state.me?.role!=='owner')return `<section class="panel">${T('Owner only','للمالك فقط')}</section>`;return `<section class="panel"><div class="panel-head"><div><h2>${T('Users & Permissions','المستخدمون والصلاحيات')}</h2><p>${T('RTM scope + page access + allowed actions','نطاق RTM + الصفحات + الأفعال المسموحة')}</p></div><button id="add-user" class="accent">＋ ${T('Add user','إضافة مستخدم')}</button></div><div class="user-grid">${state.users.map(u=>`<article class="user-card"><div><span class="user-avatar">${esc((u.displayName||u.username).slice(0,2).toUpperCase())}</span><div><h3>${esc(u.displayName||u.username)}</h3><small>@${esc(u.username)} · ${u.role==='owner'?'OWNER':'RTM USER'}</small></div></div><p><b>${T('Data:','البيانات:')}</b> ${u.allRtms?T('All RTMs','كل RTMs'):esc((u.rtms||[]).join(' + ')||'—')}</p><p><b>${T('Pages:','الصفحات:')}</b> ${fmt((u.pages||[]).length)} · <b>${T('Actions:','الأفعال:')}</b> ${esc((u.actions||[]).join(', '))}</p><footer><span class="status-dot ${u.active?'on':'off'}"></span>${u.active?T('Active','نشط'):T('Inactive','موقوف')}${u.role!=='owner'?`<button data-edit-user="${esc(u.username)}">${T('Edit permissions','تعديل الصلاحيات')}</button>`:''}</footer></article>`).join('')}</div></section><section class="panel"><h2>${T('Security model','نموذج الأمان')}</h2><p>${T('RTM data scope is enforced before data leaves the server. Users cannot export records outside their assigned RTMs. Settings and user management are Owner-only.','نطاق RTM يتم تطبيقه قبل خروج البيانات من السيرفر. لا يمكن للمستخدم تصدير سجلات خارج المناطق المسموحة له. الإعدادات وإدارة المستخدمين للمالك فقط.')}</p></section>`}
async function loadUsers(){if(state.me?.role!=='owner')return;state.users=(await api.call('users')).users||[]}
function userEditor(username){const user=state.users.find(x=>x.username===username)||{username:'',displayName:'',active:true,allRtms:false,rtms:[],pages:['dashboard','presence','availability','execution','market','performance','geo','stores','newstores','photos','all','reports'],actions:['view','export','print']};const isNew=!username;const rtms=[...new Set(rows.map(r=>r.RTM).filter(Boolean))].sort();showDialog(`<h2>${isNew?T('Add RTM user','إضافة مستخدم RTM'):esc(user.displayName)}</h2><div class="user-form"><label>${T('Username','اسم الدخول')}<input id="u-username" ${!isNew?'disabled':''} value="${esc(user.username)}"></label><label>${T('Display name','الاسم الظاهر')}<input id="u-name" value="${esc(user.displayName||'')}"></label><label>${T('Password','كلمة المرور')}<input id="u-password" type="password" placeholder="${isNew?'Required / مطلوبة':T('Leave blank to keep it','اتركها فارغة بدون تغيير')}"></label><label class="checkline"><input id="u-active" type="checkbox" ${user.active?'checked':''}> ${T('Active account','حساب نشط')}</label><h3>${T('Data Scope · RTM','نطاق البيانات · RTM')}</h3><label class="checkline"><input id="u-all" type="checkbox" ${user.allRtms?'checked':''}> ${T('All RTMs · including future RTMs','كل RTMs · بما فيها أي RTM جديد')}</label><div class="permission-grid">${rtms.map(v=>`<label><input type="checkbox" data-u-rtm="${esc(v)}" ${(user.rtms||[]).includes(v)?'checked':''}> ${esc(v)}</label>`).join('')}</div><h3>${T('Page Access','صلاحيات الصفحات')}</h3><div class="permission-grid">${['dashboard','presence','availability','execution','market','performance','geo','stores','newstores','photos','all','reports','health','optional'].map(v=>`<label><input type="checkbox" data-u-page="${v}" ${(user.pages||[]).includes(v)?'checked':''}> ${label(v)}</label>`).join('')}</div><h3>${T('Actions','الأفعال')}</h3><div class="permission-grid">${[['view','View'],['export','Export'],['print','Print / PDF'],['download','Raw download']].map(([v,l])=>`<label><input type="checkbox" data-u-action="${v}" ${(user.actions||[]).includes(v)?'checked':''}> ${l}</label>`).join('')}</div><div class="scope-preview"><b>${T('Preview scope','معاينة النطاق')}</b><span id="scope-count"></span></div><button id="save-user" class="accent">${T('Save user','حفظ المستخدم')}</button></div>`);const updatePreview=()=>{const all=$('#u-all').checked,sel=[...document.querySelectorAll('[data-u-rtm]:checked')].map(x=>x.dataset.uRtm);const count=all?unique(rows):unique(rows.filter(r=>sel.includes(String(r.RTM))));$('#scope-count').textContent=`${all?T('All RTMs','كل RTMs'):sel.join(' + ')||'—'} · ${fmt(count)} ${T('stores currently visible','محل ظاهر حاليًا')}`};document.querySelectorAll('[data-u-rtm],#u-all').forEach(x=>x.onchange=updatePreview);updatePreview();$('#save-user').onclick=async()=>{const payload={username:$('#u-username').value.trim(),displayName:$('#u-name').value.trim(),password:$('#u-password').value,active:$('#u-active').checked,allRtms:$('#u-all').checked,rtms:[...document.querySelectorAll('[data-u-rtm]:checked')].map(x=>x.dataset.uRtm),pages:[...document.querySelectorAll('[data-u-page]:checked')].map(x=>x.dataset.uPage),actions:[...document.querySelectorAll('[data-u-action]:checked')].map(x=>x.dataset.uAction)};if(isNew&&!payload.password)return toast(T('Password is required','كلمة المرور مطلوبة'));try{await api.call('saveUser',{user:payload});}catch(e){return toast(e.message)}await loadUsers();$('#detail').close();render();toast(T('User saved','تم حفظ المستخدم'))}}
function loginScreen(message=''){
 document.documentElement.dataset.theme=state.theme;
 document.documentElement.dir='ltr';
 $('#app').innerHTML=`<main class="login-shell login-centered">
   <div class="login-bg" aria-hidden="true"></div>
   <div class="login-vignette" aria-hidden="true"></div>
   <section class="login-center-wrap">
     <form id="login-form" class="login-center-card" novalidate>
       <div class="login-center-brand login-logo-shine">
         <img src="./assets/gorilla-logo.png" alt="Gorilla Energy Drink">
       </div>
       <div class="login-center-slogan">POWER YOUR<br><span>FIELD INSTINCT</span></div>
       <p class="login-center-sub">${T('Secure field intelligence for presence, execution, opportunity and TDM performance.','ذكاء ميداني آمن لمتابعة التواجد والتنفيذ والفرص وأداء الـ TDMs.')}</p>
       ${message?`<div class="login-error" role="alert">${esc(message)}</div>`:''}
       <label>${T('Username','اسم المستخدم')}<input id="login-user" autocomplete="username" required autofocus></label>
       <label>${T('Password','كلمة المرور')}<input id="login-pass" type="password" autocomplete="current-password" required></label>
       <button id="login-submit" class="accent login-submit" type="submit">${T('ENTER DASHBOARD','دخول لوحة المعلومات')} <span>→</span></button>
       <div id="login-status" class="login-status" aria-live="polite"></div>
       <small class="login-foot">GORILLA FIELD INTELLIGENCE · SECURE ACCESS</small>
     </form>
   </section>
 <footer class="login-copyright">© 2026 Ahmed Salim. All rights reserved.</footer></main>`;
 attachPasswordEyes($('#app'),state.lang==='ar');
 const form=$('#login-form'), button=$('#login-submit'), status=$('#login-status');
 form.addEventListener('submit',async e=>{
   e.preventDefault();unlockAlertAudio();
   const username=$('#login-user').value.trim(), password=$('#login-pass').value;
   if(!username||!password){status.textContent=T('Enter username and password.','اكتب اسم المستخدم وكلمة المرور.');return;}
   button.disabled=true;button.classList.add('busy');status.textContent=T('Signing in…','جاري تسجيل الدخول…');
   try{
     if(location.protocol==='file:') throw new Error(T('Open the app through start.bat, not by double-clicking index.html.','شغّل البرنامج من start.bat، وليس بفتح index.html مباشرة.'));
           const out=await api.call('login',{username,password,bootstrap:true,format:'columns'});
      if(!out.user||!out.token)throw new Error('Invalid login response');
      api.setToken(out.token);state.me=out.user;state.filters={};state.tab='dashboard';
status.textContent=T('Signed in · loading latest prepared data…','تم الدخول · جاري تحميل أحدث بيانات جاهزة…');
await refresh(true,out.bootstrap);
   }catch(err){
     button.disabled=false;button.classList.remove('busy');status.textContent='';loginScreen(err.message||T('Login failed','فشل تسجيل الدخول'));
   }
 });
}

function render(){
 stopHero();
 if(!data||!state.me)return; if(map){map.stop();map.remove();map=null;}persist();document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';document.documentElement.dataset.theme=state.theme;
 if(!allowedPage(state.tab)&&!['settings','users'].includes(state.tab))state.tab='dashboard';if((state.tab==='settings'||state.tab==='users')&&state.me.role!=='owner')state.tab='dashboard';
 if(state.tab==='optional'&&(state.sheet==='All'||!data.sheets[state.sheet]))state.sheet=Object.keys(data.sheets).find(n=>n!=='All')||'All';
 activeRows=scoped();const issues=health(rows,data.sheets.All.columns,state.settings),dates=rows.map(r=>r._date).filter(Boolean).sort();const scope=state.me.allRtms||state.me.role==='owner'?T('All RTMs','كل RTMs'):(state.me.rtms||[]).join(' + ');
 $('#app').innerHTML=`<aside class="sidebar"><div class="brand brand-word logo-shine"><img class="official-logo" src="./assets/gorilla-logo.png" alt="Gorilla Energy Drink"></div><nav aria-label="${T('Main navigation','القائمة الرئيسية')}">${navHTML()}</nav><div class="sidebar-slogan">POWER YOUR<br>FIELD INSTINCT</div><div class="sidebar-bottom"><span class="tag">V1.5.0 · WEB</span><p>${esc(state.me.displayName||state.me.username)}</p><small>${esc(scope)}</small></div></aside><main><header class="topbar"><div class="top-search-wrap"><span>⌕</span><input id="header-search" type="search" value="${esc(state.filters.search||'')}" placeholder="${T('Search stores, TDM, area…','ابحث بالمحل أو TDM أو المنطقة…')}"></div><div class="header-actions"><button class="top-chip">${esc(scope||T('All RTMs','كل RTMs'))}</button><button id="notifications" class="top-icon notif-btn">${qicons.bell}${unreadKeys.length>0?`<span class="notif-badge">${fmt(unreadKeys.length)}</span>`:''}</button><div class="user-chip"><span>${esc((state.me.displayName||state.me.username).slice(0,2).toUpperCase())}</span><div><b>${esc(state.me.displayName||state.me.username)}</b><small>${state.me.role==='owner'?'Owner':'RTM User'}</small></div></div><button id="lang" class="top-icon">${T('AR','EN')}</button><button id="refresh" class="top-icon" title="${T('Refresh data','تحديث البيانات')}" aria-label="${T('Refresh data','تحديث البيانات')}" ${state.busy?'disabled':''}>↻</button><button id="logout" class="top-icon">↪</button></div></header><div class="content"><div class="title-row ${state.tab==='dashboard'?'dashboard-title-row':''}"><div><p class="eyebrow">GORILLA · FIELD INTELLIGENCE</p><h1>${label(state.tab)}</h1><p class="subtitle">${esc(scope)} <span>·</span> ${!dates.length?T('No valid dates','لا توجد تواريخ صالحة'):dates[0]===dates.at(-1)?dates[0]:dates[0]+' → '+dates.at(-1)} <span>·</span> ${T('Updated','تحديث')} ${new Date(data.refreshed).toLocaleTimeString(state.lang==='ar'?'ar-EG':'en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})}</p></div><div class="actions">${allowedAction('export')?`<select id="export" aria-label="${T('Export','تصدير')}"><option value="">${T('Export ↗','تصدير ↗')}</option><option value="xlsx">Excel (.xlsx)</option><option value="csv">CSV</option>${allowedAction('print')?'<option value="pdf">PDF</option>':''}</select>`:''}</div></div>${!['settings','users','dashboard'].includes(state.tab)?filtersHTML():''}${state.issue?`<div class="notice">${ilabel(state.issue)} <button id="clear-issue">${T('Remove issue filter','إلغاء تصفية المشكلة')}</button></div>`:''}${data.warnings?.length?`<div class="notice" role="status">${data.warnings.map(esc).join("<br>")}</div>`:''}<div id="view">${view(state.tab,activeRows)}</div><div id="history-container">${selectedHistory()}</div><footer>${T('All metrics respect RTM access, Cycle/Week and active filters.','كل المؤشرات تحترم صلاحية RTM والسايكل/الأسبوع والفلاتر الحالية.')}<span>© 2026 Ahmed Salim. All rights reserved.</span></footer></div></main>`;
 enhanceDashboard();bind();stopHero=bindHero($('.gorilla-carousel'),state.lang==='ar');if(state.tab==='geo')drawMap(activeRows);
}
function filtersHTML(){
 const fields=['RTM','Rep','Governorate','Area Name','Outlet Type'],filtersSource=state.tab==='optional'?supportingRows(data.sheets[state.sheet]):rows;
 const hidden=new Set(state.appSettings?.filters?.[state.tab]||[]),show=k=>!hidden.has(k);
 const available=state.tab==='optional'?supportedFilters(data.sheets[state.sheet]):null;
 const optionsFor=k=>{const opts=[...new Set((available?filterSupporting(data.sheets[state.sheet],state.filters,k):filterRows(filtersSource,state.filters,k)).map(r=>String(r[k]??'')).filter(Boolean))].sort();if(state.filters[k]&&!opts.includes(state.filters[k]))opts.push(state.filters[k]);return opts;};
 const picker=(k,caption)=>`<select data-field="${esc(k)}" aria-label="${esc(caption)}" ${available&&!available.has(k)?'disabled':''}><option value="">${T('All','الكل')} · ${esc(caption)}</option>${optionsFor(k).map(v=>`<option value="${esc(v)}" ${v===state.filters[k]?'selected':''}>${esc(k===STATUS_FIELD?statusText(v,state.lang):k==='_surveyGorilla'||k==='_juhayna'?answerText(v==='unknown'?null:v==='true',state.lang):v)}</option>`).join('')}</select>`;
 let cycles=cyclePeriods(filtersSource);const current=cycleInfo(new Date().toISOString().slice(0,10));if(state.filters._cycle&&!cycles.some(c=>c.key===state.filters._cycle)){const extra=cycleInfo(state.filters._cycle);if(extra)cycles=[extra,...cycles];}
 const cycleOpts=cycles.map(c=>`<option value="${c.key}" ${state.filters._cycle===c.key?'selected':''}>Cycle ${c.cycle} · ${shortDate(c.start)} – ${shortDate(c.end)}</option>`).join('');
 const selectedCycle=cycles.find(c=>c.key===state.filters._cycle)||current;
 const primary=(show('cycle')||show('week'))?`<div class="filter-primary">${show('cycle')?`<label>${T('Cycle','سايكل')}<select id="cycle-filter"><option value="">${T('All cycles','كل السايكلز')}</option>${cycleOpts}</select></label>`:''}${show('week')?`<label>${T('Week','الأسبوع')}<select id="week-filter" ${state.filters._cycle?'':'disabled'}><option value="">${T('All cycle','السايكل كامل')}</option><option value="1" ${state.filters._week==='1'?'selected':''}>Week 1${selectedCycle?' · '+shortDate(selectedCycle.start)+' – '+shortDate(addDays(selectedCycle.start,6)):''}</option><option value="2" ${state.filters._week==='2'?'selected':''}>Week 2${selectedCycle?' · '+shortDate(addDays(selectedCycle.start,7))+' – '+shortDate(selectedCycle.end):''}</option></select></label>`:''}<span class="cycle-badge">${current?T('Current','الحالي')+`: Cycle ${current.cycle} · Week ${current.week}`:''}</span></div>`:'';
 const searchDate=`<div class="search-row">${show('search')?`<label class="search">⌕ <input id="search" type="search" value="${esc(state.filters.search||'')}" placeholder="${T('Search outlet, client code, TDM…','ابحث بالمحل، كود العميل، TDM…')}" aria-label="${T('Global search','البحث العام')}"></label>`:''}${show('date')?`<select id="preset" aria-label="${T('Date preset','الفترة الزمنية')}"><option value="">${T('Date presets','فترات سريعة')}</option>${[['all',T('All dates','كل التواريخ')],['latest',T('Latest data day','آخر يوم بالملف')],['today',T('Today','اليوم')],['7',T('Last 7 days','آخر ٧ أيام')],['30',T('Last 30 days','آخر ٣٠ يوم')],['month',T('This month','هذا الشهر')]].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><label class="date">${T('From','من')}<input id="from" type="date" value="${esc(state.filters.from||'')}"></label><label class="date">${T('To','إلى')}<input id="to" type="date" value="${esc(state.filters.to||'')}"></label>`:''}</div>`;
 const mapKey={'RTM':'rtm','Rep':'tdm','Governorate':'governorate','Area Name':'area','Outlet Type':'outlet'};
 const visibleFields=fields.filter(k=>show(mapKey[k]));
 const row=`<div class="filter-row">${visibleFields.map(k=>picker(k,fieldLabel(k))).join('')}<button id="clear">${T('Clear filters','مسح الفلاتر')}</button><span class="result-count">${fmt((available?filterSupporting(data.sheets[state.sheet],state.filters):filterRows(filtersSource,state.filters)).length)} ${T('visits','زيارة')}</span></div>`;
 const survey=(show('gorilla')||show('juhayna')||show('status'))?`<div class="survey-row">${show('gorilla')?`<label>${T('Gorilla availability question','سؤال تواجد جوريلا')}${picker('_surveyGorilla',T('Gorilla question','سؤال جوريلا'))}</label>`:''}${show('juhayna')?`<label>${T('Juhayna question','سؤال جهينة')}${picker('_juhayna',T('Juhayna question','سؤال جهينة'))}</label>`:''}${show('status')?`<label>${T('Visit status','حالة الزيارة')}${picker(STATUS_FIELD,T('Status','الحالة'))}</label>`:''}</div>`:'';
 return `<section class="filter-panel">${primary}${searchDate}${row}${survey}</section>`;
}
function view(tab,rs){
 const stores=latest(rs),k=kpis(rs);
 if(tab==='reports')return reportsView(rs);
 if(tab==='tdmphotos')return tdmPhotosView();
 if(tab==='presencetrends')return comparisonView(rs,comparisonMode,{esc,fmt,T,filters:state.filters},true);
 if(tab==='users')return usersView();
 if(tab==='presence')return presenceView(currentPresence(),state.presenceMode,{T,esc,fmt,card,page:state.page,pagination,lang:state.lang});
 if(tab==='dashboard')return dashboard(rs);
 if(tab==='all')return tableView(rs);
 if(tab==='stores')return `<section class="panel"><h2>${T('Outlet directory · select a store','دليل المحلات · اختر محلًا')}</h2><p>${T('One row per Client Code. Open a store for its complete history across the current workbook.','صف واحد لكل كود محل. افتح المحل لعرض تاريخه الكامل داخل الملف الحالي.')}</p>${storeTable(stores)}</section>`;
 if(tab==='performance'){
 const reps=group(rs,'Rep').map(([rep,count])=>{const visits=rs.filter(r=>r.Rep===rep),m=kpis(visits);return {'Rep':rep,'Visits':count,'Outlets':m.stores,'Success %':m.success==null?null:+(m.success*100).toFixed(1),'Avg minutes':m.duration,'Presence %':m.presence==null?null:+(m.presence*100).toFixed(1),'Visit hours':sum(visits,'_duration')/60,'Orders':m.orders}});
 return `<div class="metrics">${card(T('Active TDMs','المندوبون النشطون'),fmt(reps.length),T('Within filters','داخل الفلاتر'))}${card(T('Average visit','متوسط الزيارة'),duration(k.duration),T('HH:MM:SS · valid duration records','ساعة:دقيقة:ثانية · المدد الصالحة'))}${card(T('Recorded visit time','وقت الزيارات المسجّل'),duration(rs.length?sum(rs,'_duration'):null),T('HH:MM:SS · recorded visit time','ساعة:دقيقة:ثانية · وقت الزيارات المسجل'))}</div><div class="grid two">${bars(T('TDM ranking · visits','ترتيب المندوبين · زيارات'),group(rs,'Rep'),'Rep')}${bars(T('Visits by hour','الزيارات حسب الساعة'),group(rs,'Visit Hour').sort((a,b)=>Number(a[0])-Number(b[0])),'Visit Hour')}</div><section class="panel"><h2>${T('Performance scorecard','جدول الأداء')}</h2>${simpleTable(reps,Object.keys(reps[0]||{}),'Rep')}</section>`;
 }
 if(tab==='availability')return `<div class="metrics">${card(T('Avg available SKUs','متوسط الأصناف المتاحة'),fmt(k.availability,1),T('Latest visit · six listed SKUs','آخر زيارة · ستة أصناف'))}${card(T('Full assortment','تشكيلة كاملة'),fmt(stores.filter(r=>r._availability===6).length),T('Outlets with all six SKUs','محلات بها الأصناف الستة'))}${card(T('Zero availability','توافر صفر'),fmt(stores.filter(r=>r._availability===0).length),T('Measured outlets with no SKUs','محلات مقاسة بدون أصناف'))}</div><div class="grid two">${bars(T('SKU distribution · outlets','توزيع الأصناف · محلات'),SKU.map(s=>[s,stores.filter(r=>r._skus.find(x=>x.name===s)?.quantity>0).length]),'_sku')}${bars(T('SKU facings','واجهات الأصناف'),SKU.map(s=>[s,stores.reduce((a,r)=>a+(r._skus.find(x=>x.name===s)?.quantity||0),0)]),'_sku')}</div>${bars(T('Assortment depth · click to investigate','عمق التشكيلة · اضغط للفحص'),group(stores,'_availability'),'_availability')}<section class="panel"><div class="panel-head"><h2>${T('Outlets requiring replenishment','محلات تحتاج استكمال الأصناف')}</h2><button data-filter="_availability" data-value="0">${T('Out of Stock only','Out of Stock فقط')}</button></div>${storeTable(stores.filter(r=>r._availability!==null&&r._availability<6))}</section>`;
 if(tab==='market')return `<div class="metrics">${card(T('Gorilla presence','تواجد جوريلا'),pct(k.presence),T('Latest outlet visit','آخر زيارة للمحل'))}${card(T('Share of shelf','حصة الرف'),pct(k.share),T('Σ Gorilla ÷ Σ all facings','إجمالي جوريلا ÷ إجمالي الواجهات'))}${card(T('Without Gorilla','بدون جوريلا'),fmt(stores.filter(r=>r._presence===false).length),T('Known absence only','غياب مؤكد فقط'))}</div><div class="grid two">${bars(T('Competitive shelf landscape','واجهات المنافسين'),[['Gorilla',sum(stores,'_gorilla')],...BRANDS.map(b=>[b,sum(stores,b)])],'_brand')}${bars(T('Gorilla presence by territory · outlets','تواجد جوريلا حسب المنطقة · محلات'),group(stores.filter(r=>r._presence===true),'RTM'),'RTM')}</div><section class="panel"><div class="panel-head"><h2>${T('Distribution opportunities','فرص التوزيع')}</h2><button data-filter="_presence" data-value="false">${T('Filter all views','تصفية كل العروض')}</button></div><p>${T('Stores with known Gorilla absence, ranked by competitor facings. Strong-store alerts require an explicit strong-store flag; blank flags are not inferred.','محلات غياب جوريلا المؤكد، مرتبة بواجهات المنافسين. تنبيه المحل القوي يتطلب علامة صريحة؛ الخانات الفارغة لا تعني محلًا قويًا.')}</p>${storeTable(stores.filter(r=>r._presence===false).sort((a,b)=>(b._competitor??0)-(a._competitor??0)))}</section>`;
 if(tab==='execution'){
 const eligible=stores.filter(r=>r._availability!==null&&r._gorilla!==null&&r._competitor!==null&&r._gorilla+r._competitor>0&&r._posm!==null),perfect=eligible.filter(r=>r._availability>=state.settings.perfectAvailability&&r._gorilla/(r._gorilla+r._competitor)*100>=state.settings.perfectShare&&r._posm>0);
 return `<div class="notice">${T('Perfect Store is a configurable V1 rule: assortment target + shelf-share target + at least one POSM unit. It is not a certified business standard.','Perfect Store قاعدة V1 قابلة للتعديل: هدف التشكيلة + هدف حصة الرف + وحدة دعاية واحدة على الأقل. ليست معيارًا تجاريًا معتمدًا.')}</div><div class="metrics">${card(T('POSM units','وحدات الدعاية'),fmt(k.posm),T('Sum of detailed POSM columns','مجموع أعمدة الدعاية التفصيلية'))}${card(T('Outlets with POSM','محلات بها دعاية'),fmt(stores.filter(r=>r._posm>0).length),T('Latest outlet visit','آخر زيارة للمحل'))}${card(T('Perfect Store','المحل المثالي'),eligible.length?pct(perfect.length/eligible.length):'—',fmt(perfect.length)+' / '+fmt(eligible.length)+' '+T('eligible outlets','محلات قابلة للتقييم'))}</div><div class="grid two">${bars(T('POSM execution by type','الدعاية حسب النوع'),POSM.map(p=>[p,sum(stores,p)]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]))}${bars(T('POSM units by territory','وحدات الدعاية حسب المنطقة'),group(stores,'RTM','_posm'),'RTM')}</div><section class="panel"><h2>${T('Execution follow-up','متابعة التنفيذ')}</h2>${storeTable(stores.filter(r=>!perfect.includes(r)))}</section>`;
 }
 if(tab==='geo')return `<section class="panel"><div class="panel-head"><h2>${T('Outlet coverage map','خريطة تغطية المحلات')}</h2><span>${fmt(stores.filter(r=>r._geo).length)} ${T('mapped outlets','محلات على الخريطة')}</span></div><div class="map-legend"><span><i style="background:#66d9ef"></i>${T('Gorilla present','جوريلا موجودة')}</span><span><i style="background:#ed8b56"></i>${T('Gorilla absent','جوريلا غير موجودة')}</span><span>${T('Click a point for Store 360','اضغط على نقطة لعرض المحل 360')}</span></div><div id="map" class="map"></div><p id="map-status" style="margin-top:14px">${T('Map tiles require internet. No API key or paid service.','الخريطة تحتاج إنترنت. لا تحتاج مفتاح API أو خدمة مدفوعة.')}</p><small>${fmt(stores.filter(r=>!r._geo).length)} ${T('outlets excluded because coordinates are invalid or missing.','محلات مستبعدة بسبب إحداثيات مفقودة أو غير صالحة.')}</small></section><div class="grid two">${bars(T('Visits by governorate','الزيارات حسب المحافظة'),group(rs,'Governorate'),'Governorate')}${bars(T('Visits by area','الزيارات حسب المنطقة'),group(rs,'Area Name'),'Area Name')}</div>`;
 if(tab==='photos')return galleryView(rs);
 if(tab==='health')return healthView(rs);
 if(tab==='notifications')return notificationView();
 if(tab==='settings')return settingsView();
 if(tab==='optional')return optionalView();
 return empty();
}
function simpleTable(records,columns,filterKey){return records.length?`<div class="table-wrap"><table><thead><tr>${columns.map(c=>`<th>${esc(fieldLabel(c))}</th>`).join('')}</tr></thead><tbody>${records.map(r=>`<tr>${columns.map(c=>`<td>${filterKey===c?`<button class="link-button" data-filter="${esc(c)}" data-value="${esc(r[c])}">${esc(display(c,r[c]))}</button>`:cellHTML(r,c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty();}
function cellHTML(r,c,interactive=true){
 if(isLocationField(c)){const url=googleMapsUrl(r);return url?`<a href="${url}" target="_blank" rel="noopener noreferrer">${T('Open Location','افتح اللوكيشن')}</a>`:'—';}
 const id=r._id??r['Client Code'];if(interactive&&['Client','Client Local Name','Client Code'].includes(c)&&id!=null&&id!=='')return `<button class="link-button" data-store="${esc(id)}">${esc(r[c]??id)}</button>`;
 const value=display(c,r[c]);return esc(typeof value==='number'&&!/Code|ID/.test(c)?fmt(value,3):value);
}
function storeTable(stores){const page=stores.slice(state.page*40,state.page*40+40);return `<div class="table-wrap"><table><thead><tr>${[T('Outlet','المحل'),T('Client Code','كود العميل'),'TDM',T('Territory','المنطقة'),T('Last visit','آخر زيارة'),T('SKUs','أصناف'),T('Facings','واجهات'),'POSM'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${page.map(r=>`<tr><td><button class="link-button" data-store="${esc(r._id)}">${esc(r.Client||r['Client Local Name']||r._id)}</button></td><td>${esc(r._id)}</td><td>${esc(r.Rep)}</td><td>${esc(r.RTM)}</td><td>${esc(r._date)}</td><td>${fmt(r._availability)}</td><td>${fmt(r._gorilla)}</td><td>${fmt(r._posm)}</td></tr>`).join('')}</tbody></table></div>${!stores.length?empty():pagination(stores.length,40)}`}
function pagination(count,size=40){return `<div class="pager"><span>${fmt(count)} ${T('records','سجل')} · ${fmt(Math.min(count,state.page*size+1))}–${fmt(Math.min(count,(state.page+1)*size))}</span><button data-page="${state.page-1}" ${state.page===0?'disabled':''}>${T('Previous','السابق')}</button><button data-page="${state.page+1}" ${(state.page+1)*size>=count?'disabled':''}>${T('Next','التالي')}</button></div>`}
function tableView(rs){return `<section class="panel"><div class="panel-head"><h2>${T('All · official visit records','All · سجلات الزيارات الرسمية')}</h2><button id="columns">${T('Manage columns','إدارة الأعمدة')} (${state.columns.length})</button></div><p>${T('Select a store name or code to see its positive Gorilla visits below.','اضغط على اسم المحل أو كوده لعرض زيارات تواجد جوريلا أسفل الصفحة.')}</p>${simpleTable(rs.slice(state.page*40,state.page*40+40),state.columns)}${!rs.length?'':pagination(rs.length)}</section>`;}
function photosFor(rs){return rs.flatMap(r=>r._photos.map(p=>({...p,id:r._id,client:r.Client,date:r._date,row:r._row})));}
function galleryView(rs){const all=photosFor(rs),photos=all.filter(p=>!state.photoCategory||p.category===state.photoCategory),categories=[...new Set(all.map(p=>p.category))];return `<section class="panel"><div class="panel-head"><h2>${T('Field photo evidence','صور الزيارات الميدانية')}</h2><span>${fmt(photos.length)} ${T('photos','صورة')}</span></div><select id="photo-category" aria-label="${T('Photo category','نوع الصور')}" style="max-width:100%;margin-bottom:15px"><option value="">${T('All photo categories','كل أنواع الصور')}</option>${categories.map(c=>`<option ${c===state.photoCategory?'selected':''}>${esc(c)}</option>`).join('')}</select><p>${T('Images load from the original source when viewed. Failed images are marked; their URLs remain available.','الصور تُحمّل من المصدر الأصلي عند العرض. يتم توضيح الصور التي تعذر تحميلها مع إتاحة روابطها.')}</p><div class="gallery">${photos.slice(state.page*24,state.page*24+24).map(p=>photoCard(p)).join('')||empty()}</div>${pagination(photos.length,24)}</section>`}
function photoCard(p){return `<button class="photo" data-photo="${esc(p.url)}" data-caption="${esc(p.client+' · '+p.category)}"><img src="${esc(p.url)}" alt="${esc(p.category)}" loading="lazy" referrerpolicy="no-referrer"><div>${esc(p.client||p.id)}<small>${esc(p.date)}</small><p>${esc(p.category)}</p></div></button>`}
function healthView(rs){const issues=health(rs,data.sheets.All.columns,state.settings),groups=group(issues,'kind');return `<div class="metrics">${card(T('Critical findings','ملاحظات حرجة'),fmt(issues.filter(i=>i.severity==='critical').length),T('Findings, not unique visits','عدد الملاحظات وليس الزيارات الفريدة'))}${card(T('Warnings','تحذيرات'),fmt(issues.filter(i=>i.severity==='warning').length),T('Review before reporting','راجع قبل اعتماد التقرير'))}${card(T('Ignored #REF! columns','أعمدة #REF! المستبعدة'),fmt(data.ignored.All.length),T('Excluded as requested','مستبعدة حسب الاتفاق'))}</div><section class="panel"><h2>${T('Findings · click to inspect affected visits','الملاحظات · اضغط لفحص الزيارات المتأثرة')}</h2>${groups.map(([kind,count])=>`<button class="issue" data-issue="${kind}"><span>${ilabel(kind)} <small class="severity ${issues.find(x=>x.kind===kind).severity}">${T(issues.find(x=>x.kind===kind).severity,({critical:'حرج',warning:'تحذير',info:'معلومة'})[issues.find(x=>x.kind===kind).severity])}</small></span><b>${fmt(count)} ↗</b></button>`).join('')||empty()}</section><div class="grid two"><section class="panel"><h2>${T('Schema changes since last refresh','تغييرات الأعمدة منذ التحديث السابق')}</h2>${data.schemaChanges.length?simpleTable(data.schemaChanges,['sheet','column','type']):`<p>${T('No changes detected this session. All unknown columns remain available in the column manager.','لم يتم رصد تغييرات في هذه الجلسة. الأعمدة الجديدة متاحة في إدارة الأعمدة.')}</p>`}<p>${T('Excluded columns: ','الأعمدة المستبعدة: ')}${data.ignored.All.map(esc).join(', ')||'—'}</p></section><section class="panel"><h2>${T('Photo link checks','فحص روابط الصور')}</h2><p>${fmt(failedPhotos.size)} ${T('unique image URLs failed during this browser session. Unopened photos have not been remotely checked.','روابط صور فشل تحميلها أثناء جلسة المتصفح. الصور التي لم تُفتح لم يتم فحصها عن بُعد.')}</p><p>${T('POSM is recomputed from detailed columns. Formula discrepancies are shown as information. Missing measurement data is not replaced with a business assumption.','مواد الدعاية محسوبة من أعمدتها التفصيلية. اختلافات المعادلات تظهر كملاحظات معلوماتية. البيانات المفقودة لا تُستبدل بافتراض تجاري.')}</p></section></div>`}
function settingsView(){
 if(state.me?.role!=='owner')return `<section class="panel"><h2>${T('Owner only','للمالك فقط')}</h2><p>${T('Settings are not available for this account.','الإعدادات غير متاحة لهذا الحساب.')}</p></section>`;
 const app=state.appSettings||data.appSettings||{};const hero=app.hero||{};
 return `<div class="settings-grid"><section class="panel"><h2>${T('Homepage Hero','الهيرو الرئيسي')}</h2><label class="setting">${T('Show hero','إظهار الهيرو')}<input id="hero-enabled" type="checkbox" ${hero.enabled!==false?'checked':''}></label><label class="setting">${T('Autoplay seconds','ثواني الحركة')}<input id="hero-speed" type="number" min="3" max="20" value="${Number(hero.autoplaySeconds||6)}"></label>${heroEditor(hero,state.lang==='ar')}<button id="save-appearance" class="accent">${T('Save appearance','حفظ المظهر')}</button></section><section class="panel"><div class="panel-head"><h2>${T('Users & Permissions','المستخدمون والصلاحيات')}</h2><button data-tab="users" class="accent">${T('Manage users','إدارة المستخدمين')}</button></div><p>${T('Control RTM scope, pages and actions for every account. Data scope is enforced by the server.','تحكم في نطاق RTM والصفحات والأفعال لكل حساب. نطاق البيانات مطبق على مستوى السيرفر.')}</p></section><section class="panel"><h2>${T('Alert thresholds','حدود التنبيهات')}</h2><label class="setting">${T('Very short visit below (HH:MM:SS)','زيارة قصيرة أقل من (HH:MM:SS)')}<input id="short-duration" class="time-value" type="text" value="${duration(state.settings.short)}"></label>${[['share',T('Low shelf share below (%)','حصة رف أقل من (%)')],['availability',T('Low availability at or below','توافر أقل من أو يساوي')],['perfectAvailability',T('Perfect Store minimum SKUs','أقل عدد أصناف للمحل المثالي')],['perfectShare',T('Perfect Store minimum shelf share (%)','أقل حصة رف للمحل المثالي (%)')]].map(([k,l])=>`<label class="setting">${l}<input type="number" data-setting="${k}" min="0" max="100" value="${state.settings[k]}"></label>`).join('')}</section><section class="panel"><h2>${T('Navigation visibility','إظهار صفحات التطبيق')}</h2>${Object.keys(labels).filter(k=>!['dashboard','settings','users'].includes(k)).map(k=>`<label class="setting">${label(k)}<input type="checkbox" data-tab-setting="${k}" ${state.settings.tabs[k]!==false?'checked':''}></label>`).join('')}</section><section class="panel"><h2>${T('Filter controls by page','إظهار الفلاتر حسب الصفحة')}</h2><label class="stack-setting">${T('Page','الصفحة')}<select id="filter-page-setting">${['dashboard','presence','performance','availability','market','execution','geo','stores','photos','all','reports'].map(k=>`<option value="${k}" ${state.filterSettingsPage===k?'selected':''}>${label(k)}</option>`).join('')}</select></label><div class="permission-grid">${[['cycle','Cycle'],['week','Week'],['search','Search'],['date','Date Range'],['rtm','RTM'],['tdm','TDM'],['governorate','Governorate'],['area','Area'],['outlet','Outlet Type'],['gorilla','Gorilla Question'],['juhayna','Juhayna Question'],['status','Visit Status']].map(([k,l])=>`<label><input type="checkbox" data-filter-visibility="${k}" ${!(state.appSettings?.filters?.[state.filterSettingsPage]||[]).includes(k)?'checked':''}> ${l}</label>`).join('')}</div><small>${T('Uncheck a filter to hide it only on the selected page.','أزل العلامة لإخفاء الفلتر في الصفحة المختارة فقط.')}</small></section><section class="panel"><h2>${T('Cycle engine','نظام السايكل')}</h2><p><b>Anchor:</b> 29 Aug 2026 · Saturday</p><p>${T('Cycle 1 (2 weeks) → Cycle 2 (2 weeks) → repeat. Each week runs Saturday to Friday.','سايكل 1 أسبوعين ← سايكل 2 أسبوعين ← يتكرر. كل أسبوع من السبت للجمعة.')}</p></section></div>`;
}
function optionalView(){const names=Object.keys(data.sheets).filter(n=>n!=='All');if(!names.length)return empty();if(!names.includes(state.sheet))state.sheet=names[0];const sheet=data.sheets[state.sheet],selected=filterSupporting(sheet,state.filters),unsupported=Object.keys(state.filters).filter(k=>state.filters[k]&&!supportedFilters(sheet).has(k));return `<section class="panel"><div class="panel-head"><h2>${T('Supporting source sheets','أوراق المصدر المساندة')}</h2><select id="sheet-select">${names.map(n=>`<option ${n===state.sheet?'selected':''}>${esc(n)}</option>`).join('')}</select></div><p>${T('Filters and exports apply to this sheet. Every source column is included. Unavailable fields are disabled.','الفلاتر والتصدير لهذه الورقة. كل أعمدة المصدر ظاهرة. الحقول غير المتاحة معطّلة.')}</p>${unsupported.length?`<p role="status">${T('Not available in this sheet: ','غير متاح في هذه الورقة: ')}${unsupported.map(k=>esc(fieldLabel(k))).join('، ')}</p>`:''}${simpleTable(selected.slice(state.page*40,state.page*40+40),sheet.columns)}${pagination(selected.length)}</section>`}
function bind(){
 if($('#comparison-mode'))$('#comparison-mode').onchange=e=>{comparisonMode=e.target.value;render();};
 document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{const t=el.dataset.tab;if(!allowedPage(t))return;state.tab=t;state.page=0;render()});
 document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>apply(el.dataset.filter,el.dataset.value));document.querySelectorAll('[data-field]').forEach(el=>el.onchange=()=>apply(el.dataset.field,el.value));
 if($('#lang'))$('#lang').onclick=()=>{state.lang=state.lang==='en'?'ar':'en';render()};if($('#refresh'))$('#refresh').onclick=()=>checkFreshness(true);if($('#logout'))$('#logout').onclick=async()=>{try{await api.call('logout')}catch{}finally{endSession()}};
 if($('#export'))$('#export').onchange=e=>{if(e.target.value)exportData(e.target.value);e.target.value=''};
 if($('#clear'))$('#clear').onclick=()=>{state.filters={};state.issue=null;state.page=0;render()};
 if($('#search'))$('#search').oninput=e=>{const v=e.target.value,p=e.target.selectionStart;clearTimeout(window.searchTimer);window.searchTimer=setTimeout(()=>{apply('search',v);$('#search')?.focus();$('#search')?.setSelectionRange(p,p)},220)};if($('#header-search'))$('#header-search').oninput=e=>{const v=e.target.value,p=e.target.selectionStart;clearTimeout(window.headerSearchTimer);window.headerSearchTimer=setTimeout(()=>{apply('search',v);$('#header-search')?.focus();$('#header-search')?.setSelectionRange(p,p)},220)};
 for(const id of ['from','to'])if($('#'+id))$('#'+id).onchange=e=>{state.filters._cycle='';state.filters._week='';apply(id,e.target.value)};
 if($('#cycle-filter'))$('#cycle-filter').onchange=e=>{state.filters._cycle=e.target.value;state.filters._week='';state.filters.from='';state.filters.to='';state.page=0;render()};if($('#week-filter'))$('#week-filter').onchange=e=>{state.filters._week=e.target.value;state.page=0;render()};
 if($('#preset'))$('#preset').onchange=e=>{state.filters._cycle='';state.filters._week='';preset(e.target.value)};if($('#clear-issue'))$('#clear-issue').onclick=()=>{state.issue=null;render()};if($('#notifications'))$('#notifications').onclick=notifications;bindNotificationControls();
 document.querySelectorAll('[data-report-export]').forEach(el=>el.onclick=()=>{const old=state.tab;state.tab=el.dataset.reportExport;exportData('xlsx');state.tab=old});
 if($('#add-user'))$('#add-user').onclick=()=>userEditor();document.querySelectorAll('[data-edit-user]').forEach(el=>el.onclick=()=>userEditor(el.dataset.editUser));
 document.querySelectorAll('[data-theme-choice]').forEach(el=>el.onclick=()=>{state.theme=el.dataset.themeChoice;render()});
 if($('#save-appearance'))$('#save-appearance').onclick=saveAppearance;
 if($('#filter-page-setting'))$('#filter-page-setting').onchange=e=>{state.filterSettingsPage=e.target.value;render()};
 document.querySelectorAll('[data-filter-visibility]').forEach(el=>el.onchange=async()=>{const page=state.filterSettingsPage,all=['cycle','week','search','date','rtm','tdm','governorate','area','outlet','gorilla','juhayna','status'];state.appSettings.filters=state.appSettings.filters||{};state.appSettings.filters[page]=all.filter(k=>{const box=document.querySelector(`[data-filter-visibility="${k}"]`);return box&&!box.checked});try{state.appSettings=(await api.call('saveSettings',{settings:{filters:state.appSettings.filters}})).settings;}catch(e){return toast(e.message)}toast(T('Filter visibility saved','تم حفظ إظهار الفلاتر'))});
 bindExtra();
}
function preset(v){if(!v)return;const today=new Date(),day=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');let from='',to='';if(v==='latest'){from=to=rows.map(r=>r._date).sort().at(-1)||''}else if(v!=='all'){to=day(today);if(v==='today')from=to;else if(v==='month')from=to.slice(0,7)+'01';else{today.setDate(today.getDate()-Number(v)+1);from=day(today)}}state.filters={...state.filters,from,to};state.page=0;render()}
function endSession(message=''){sessionEpoch++;alertKeys=[];unreadKeys=[];lastSoundKeys=new Set();
 api.setToken('');data=null;rows=[];state.me=null;state.users=[];state.selectedStore=null;state.filters={};state.tab='dashboard';state.appSettings=null;state.busy=false;
 if(map){map.stop();map.remove();map=null;}document.querySelectorAll('dialog[open]').forEach(d=>d.close());loginScreen(message);
}
async function refresh(initial=false,preparedBundle=null){
 if(state.busy)return;const epoch=sessionEpoch;state.busy=true;if($('#refresh'))$('#refresh').disabled=true;
 try{
  const bundle=preparedBundle||await api.call('bootstrap',{format:'columns'});if(epoch!==sessionEpoch)return;
  state.me=bundle.user;const next=prepareBundle(bundle,data);state.appSettings=bundle.settings||{};state.users=bundle.users||[];next.appSettings=state.appSettings;
  if(state.appSettings.analysis)state.settings={...state.settings,...state.appSettings.analysis};
  state.settings.tabs=state.appSettings.tabs||state.settings.tabs||{};state.theme=state.appSettings.theme||state.theme;
  data=next;rows=normalize(data.sheets.All.rows);
  if(!state.columns)state.columns=['Date','Rep','RTM','Client','Client Code','Governorate','Area Name','Outlet Type','Availability','Duration (min)','Gorilla Share of Shelf'];
  const known=read('gorilla-known-columns',[]);if(known.length)state.columns.push(...data.sheets.All.columns.filter(c=>!known.includes(c)));
  localStorage.setItem('gorilla-known-columns',JSON.stringify(data.sheets.All.columns));
  state.columns=[...new Set(state.columns)].filter(c=>data.sheets.All.columns.includes(c));if(!state.columns.length)state.columns=data.sheets.All.columns.slice(0,10);
  updateAlerts();state.busy=false;render();
  if(initial)void checkFreshness(false);
  return true;
 }catch(e){state.busy=false;if(e.code==='UNAUTHORIZED')return endSession(T('Your session ended. Please sign in again.','انتهت الجلسة. سجّل الدخول مرة أخرى.'));if(data){render();toast(T('Refresh failed. Previous data retained: ','فشل التحديث. البيانات السابقة محفوظة: ')+e.message)}else loginScreen(e.message)}
}
async function checkFreshness(manual=false,scan=false){
 if(checking||state.busy||!state.me)return;checking=true;const epoch=sessionEpoch;
 if(manual)toast(T('Checking Drive for new files…','جاري فحص الملفات الجديدة على Drive…'));
 if($('#refresh'))$('#refresh').disabled=true;
 try{const result=await api.call(manual||scan?'sync':'status');if(epoch!==sessionEpoch)return;
  if(manual||result.sync?.revision!==data?.sync?.revision){if(!await refresh(false))return;}
  if(result.sync?.errors?.length)toast(result.sync.errors.join(' · '));
  else if(manual)toast(result.busy?T('File processing is already running. New data will appear automatically.','معالجة الملفات شغالة بالفعل. البيانات الجديدة هتظهر تلقائيًا.'):T('Latest available data loaded','تم تحميل أحدث بيانات متاحة'));
 }catch(e){if(e.code==='UNAUTHORIZED')endSession(T('Please sign in again','سجّل الدخول مرة أخرى'));else if(manual)toast(e.message);}
 finally{checking=false;if($('#refresh'))$('#refresh').disabled=false;}
}
function updateAlerts(){
 const key='gorilla-read-alerts:'+state.me.username,stored=read(key,null);
 alertKeys=notificationKeys(health(rows,data.sheets.All.columns,state.settings),rows,data.sheets);
 if(data.sync?.revision)alertKeys.push(JSON.stringify(['data',data.sync.revision]));
 const seen=new Set(stored||alertKeys.filter(k=>JSON.parse(k)[0]==='column'));
 unreadKeys=alertKeys.filter(k=>!seen.has(k));
 if(stored===null)localStorage.setItem(key,JSON.stringify([...seen]));
 const freshKeys=unreadKeys.filter(k=>!lastSoundKeys.has(k));
 if(freshKeys.length){playAlert();if(stored!==null){const groups=new Map();for(const key of freshKeys){const [kind,detail]=JSON.parse(key),title=kind==='issue'?ilabel(detail):kind==='data'?T('Data updates','تحديث البيانات'):T('Source columns','أعمدة المصدر');groups.set(title,(groups.get(title)||0)+1);}toast([...groups].map(([name,count])=>`${name}: ${fmt(count)}`).join(' · '));}}
 if(stored!==null&&freshKeys.some(k=>JSON.parse(k)[0]==='data'))void notifyDevice();lastSoundKeys=new Set(unreadKeys);
}
